                                              AND GVL_Troubleshooting.HomingM1.Step3_EncoderAvailable
                                              AND GVL_Troubleshooting.HomingM1.Step4_ContactorsReleased
                                              AND GVL_Troubleshooting.HomingM1.Step5_BrakeApplied;

